 io.drain();suppress=true;sci(SCI_SETREADONLY,FALSE);sci(SCI_SETDOCPOINTER,0,0);std::string sample="from dataclasses import dataclass\nvalue = sum(range(100))  # Orbit benchmark\n";std::string document;document.reserve(10*1024*1024);while(document.size()<10*1024*1024)document+=sample;
